def build(b):
    for level in range(1, 6):
        for prompt, correct, wrong, expl in MC[level]:
            b.mc(M, level, prompt, correct, wrong, expl)
        for prompt, word, ans, hint, expl in WRITE[level]:
            b.write(M, level, prompt, ans, hint, expl, word=word, acceptable=(["invent"] if ans == "invenció" else None))
        for s in DICTAT[level]:
            b.write(M, level, "Escolta i escriu la frase", s, f"Té {len(s.split())} paraules",
                    "Recorda la majúscula del principi i el punt del final.", dictation=True)
        for words in ORDER[level]:
            b.order(M, level, "Ordena les paraules per a formar una frase", words, ' '.join(words))
